package com.dasein.poryadok.logic

/**
 * Подсказки новичку к шагам рецепта: что значит «пассеровать», какой нужен огонь, как понять, что готово.
 * Работает без интернета — по словам в тексте шага.
 */
object CookingHints {
    private class Hint(val re: Regex, val text: String)

    private fun h(pattern: String, text: String) = Hint(Regex(pattern, RegexOption.IGNORE_CASE), text)

    private val HINTS = listOf(
        h("пассер", "Пассеровать — жарить нарезанный лук или морковь на среднем или слабом огне 5–7 минут, помешивая, пока овощи не станут мягкими и прозрачными. Корочки быть не должно."),
        h("карамелиз", "Карамелизовать — держать на среднем огне, пока сахар или лук не станут золотисто-коричневыми и сладкими. Не уходите от плиты: от золотистого до горелого — минута."),
        h("обжар|поджар|жарь|жарит|обжаривать", "Жарка: разогрейте сковороду на среднем огне 1–2 минуты, налейте 1–2 ст. л. масла — оно должно слегка «рябить». Кладите продукты в один слой, не перегружайте сковороду, иначе они начнут тушиться. Переворачивайте, когда снизу появится золотистая корочка."),
        h("туш", "Тушить — готовить под крышкой на слабом огне с небольшим количеством жидкости. Внутри должно чуть-чуть булькать, а не кипеть ключом. Иногда помешивайте и проверяйте, не выкипела ли жидкость."),
        h("бланшир", "Бланшировать — опустить продукт в кипящую воду на 1–3 минуты, затем сразу переложить в холодную воду, чтобы он перестал вариться и сохранил цвет."),
        h("на пару|пароварк", "На пару: вода кипит внизу, продукты лежат на решётке выше воды и не касаются её, крышка закрыта. Подливайте кипяток, если вода выкипает."),
        h("довести до кипения|закип|вскипят", "Закипание — когда крупные пузыри поднимаются по всей поверхности. После этого обычно убавляют огонь до слабого, чтобы жидкость лишь слегка булькала."),
        h("вари|отвар", "Варка: после закипания убавьте огонь до среднего-слабого, чтобы вода спокойно булькала. Пену с бульона снимайте ложкой. Готовность проверяйте пробой, а не только по времени."),
        h("духовк|запек|запечь|выпека", "Духовку включите заранее, за 10–15 минут, чтобы она прогрелась до нужной температуры. Ставьте форму на средний уровень, если в рецепте не сказано иначе. Без конвекции время может быть на 5–10 минут больше."),
        h("гриль", "Сковороду-гриль хорошо прогрейте (2–3 минуты на сильном огне), смажьте маслом сам продукт, а не сковороду. Не двигайте кусок, пока не появятся полоски, — тогда он легко отстанет."),
        h("взб", "Взбить — быстро перемешивать венчиком или миксером, пока масса не станет однородной и пышной. Для яичных белков нужна чистая сухая миска — капля желтка или воды помешает."),
        h("замес|тесто", "Тесто месите руками 5–10 минут, пока оно не станет гладким и не перестанет липнуть к рукам. Если липнет — подсыпайте муку по ложке, если крошится — добавьте ложку воды."),
        h("маринов|маринад", "Мариновать — перемешать продукт с маринадом, накрыть и убрать в холодильник. Даже 20–30 минут заметно добавляют вкуса, мясу лучше 2–12 часов."),
        h("до мягкост", "«До мягкости» проверяют ножом или вилкой: они должны входить легко, без усилия."),
        h("до золотист|румян|корочк", "«До золотистой корочки» — цвет как у свежего хлебного тоста. Если темнеет слишком быстро, а внутри ещё сырое, убавьте огонь."),
        h("кур|индейк|филе", "Птица готова, когда при надрезе в самом толстом месте сок прозрачный и внутри нет розового цвета. Если есть термометр — 74 °C в центре."),
        h("рыб|лосос|горбуш|треск|минта|хек|скумбри", "Рыба готова, когда мякоть стала непрозрачной и легко расслаивается вилкой. Она готовится быстро — лучше проверить на пару минут раньше."),
        h("фарш|котлет|тефтел|фрикадел", "Котлеты и тефтели: смочите руки водой — фарш не будет липнуть. Готовность — сок при надрезе прозрачный, внутри не розовое."),
        h("до готовност", "«До готовности» — пробуйте: крупы и макароны должны быть мягкими без твёрдой сердцевины, овощи — легко протыкаться, мясо — без розового сока."),
        h("крупу|рис |риса|гречк|пшен|киноа|булгур", "Крупу перед варкой промойте в сите холодной водой, пока вода не станет почти прозрачной. Не мешайте её во время варки, иначе она слипнется."),
        h("макарон|спагетт|паст|лапш", "Макароны варите в большом количестве кипящей подсоленной воды (около 1 л на 100 г), помешайте в первую минуту, чтобы не слиплись. Пробуйте за 1–2 минуты до времени на упаковке."),
        h("щепот", "Щепотка — столько, сколько берётся тремя пальцами, примерно 1/8 чайной ложки."),
        h("ст\\. ?л|ч\\. ?л|столов|чайн(ую|ой) лож", "Ст. л. — столовая ложка (около 15 мл), ч. л. — чайная ложка (около 5 мл). Ложка «с горкой» — примерно в полтора раза больше."),
        h("по вкусу", "«По вкусу» — начните с щепотки, перемешайте, попробуйте и при необходимости добавьте ещё. Убрать лишнюю соль уже не получится."),
        h("кубик", "Кубики — около 1 см. Сначала нарежьте продукт пластинами, потом пластины — брусочками, а брусочки — поперёк."),
        h("соломк", "Соломка — тонкие полоски толщиной 3–5 мм и длиной 4–5 см."),
        h("кольц|полукольц", "Кольца: лук очистите и нарежьте поперёк. Для полуколец сначала разрежьте луковицу пополам вдоль."),
        h("натр|тёрк|терк", "Натереть — на крупной стороне тёрки, если в рецепте не сказано «на мелкой». Держите продукт пальцами сверху, а не сбоку, чтобы не поранить пальцы."),
        h("остуд|остыт|настоя", "Дайте блюду постоять: так соки распределятся внутри, а вкус станет ровнее. Горячее мясо после жарки хорошо подождать 5 минут, прежде чем резать."),
        h("слив(ки|оч)|сметан|молок", "Сливки, сметану и молоко добавляйте на слабом огне и не доводите до бурного кипения — они могут свернуться."),
        h("чеснок", "Чеснок горит очень быстро и начинает горчить. Добавляйте его в конце жарки и держите на огне не дольше 30–60 секунд."),
        h("яйц|яйко|омлет|глазун", "Яйца: для омлета огонь средне-слабый, сковороду накройте крышкой — верх схватится, а низ не подгорит. Для варки опускайте яйца в кипящую воду ложкой."),
    )

    /** Подсказки к тексту шага: не больше [max], самые конкретные — первыми. */
    fun forStep(text: String, max: Int = 2): List<String> = HINTS.filter { it.re.containsMatchIn(text) }.take(max).map { it.text }
}
